#pragma material(BlendMode = "Translucent")
// A setting written twice: the later value, with a warning (DSH3262).
/// @name M_LpSettingTwice
export void M_LpSettingTwice(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    Color = float3(1.0, 0.5, 0.25);
    Base.EmissiveColor = Color;
}
